ee:variables.ee:set-variable:
%dw 2.0
import computePropEdits from dwl::assessment
output application/java
var childPom = read("<project><properties><app.runtime>4.6.0</app.runtime><java.version>8</java.version><mule.maven.plugin.version>4.4.0</mule.maven.plugin.version></properties></project>", "application/xml")
var chain = [{ path: "app/pom.xml", pom: childPom }]
var matrix = {
    target: { runtime: "4.9.18", javaVersion: "17" },
    muleArtifact: { minMuleVersion: "4.9.0", javaSpecificationVersions: ["17"] },
    gating: {
        r: { property: "app.runtime", set: "4.9.18" },
        j: { property: "java.version", set: "17" },
        m: { property: "mule.maven.plugin.version", set: "4.5.0" }
    },
    connectors: [ { property: "muleHttpConnectorVersion", set: "1.11.3" } ]
}
---
computePropEdits(chain, matrix)

%dw 2.0
import buildAssessmentResult from dwl::assessment
output application/java
var childText = "<project><properties><app.runtime>4.6.0</app.runtime><java.version>8</java.version></properties></project>"
var childPom = read(childText, "application/xml")
var chain = [{ path: "app/pom.xml", pom: childPom }]
var matrix = {
    target: { runtime: "4.9.18", javaVersion: "17" },
    muleArtifact: { minMuleVersion: "4.9.0", javaSpecificationVersions: ["17"] },
    gating: {
        r: { property: "app.runtime", set: "4.9.18" },
        j: { property: "java.version", set: "17" }
    },
    connectors: []
}
---
buildAssessmentResult(matrix, chain, childText, null, null, null, null, "myapp", "PARENT_APP", "sha123", false, false, false, [])

%dw 2.0
import classifyTopology from dwl::treeAnalysis
output application/java
var appPom = read("<project><properties><app.runtime>4.6.0</app.runtime></properties></project>", "application/xml")
var parentPom = read("<project/>", "application/xml")
var standalone = classifyTopology([{ path: "pom.xml", pom: appPom }], ["app.runtime"])
var parentApp  = classifyTopology([{ path: "app/pom.xml", pom: appPom }, { path: "pom.xml", pom: parentPom }], ["app.runtime"])
---
{ standalone: standalone, parentApp: parentApp }
